// El tipo de documento NO se infiere: lo declara el operador en el portal y
// viaja en un campo propio del payload, no metido en el nombre del archivo.
//
// El portal manda un campo "docs" con un JSON: una entrada por archivo.
//   [{ nombre_archivo, tipo_doc, documento_id, grupo_id }]
//
// El match se hace por NOMBRE DE ARCHIVO, así que no depende del orden en que
// n8n arme los binarios. Si el nombre no aparece, cae al índice; si tampoco,
// queda 'desconocido' y el switch lo manda al fallback (igual va a Drive).
//
// Compatibilidad: si no viene "docs", se usa el viejo prefijo factura__ / etc.
// para no romper nada durante la transición. Sacar ese bloque cuando el portal
// ya mande "docs" siempre.
// ============================================================================

const RAMAS = ['factura', 'anexo', 'transporte', 'packing_list'];

// Los 14 tipos del portal contra las 4 ramas del workflow.
// Lo que no está acá no tiene agente: va a Drive sin pasar por IA.
const RAMA_POR_TIPO = {
  proforma: 'factura',
  factura_comercial: 'factura',
  factura_definitiva: 'factura',
  bl: 'transporte',
  awb: 'transporte',
  crt: 'transporte',
  packing_list: 'packing_list',
  anexo: 'anexo',
};

const input = $input.all();
const out = [];

for (let idx = 0; idx < input.length; idx++) {
  const item = input[idx];
  const body = item.json?.body ?? {};

  const numeroOp = (body.numero_operacion ?? '').toString().trim();
  const operacionId = (body.operacion_id ?? '').toString().trim();
  // messageId agrupa la operación en el cuadro comparativo.
  // operacion_id es un uuid: no colisiona entre clientes como sí puede el legajo.
  const groupId = numeroOp || operacionId || ('op_' + Date.now());

  let docs = [];
  try {
    docs = typeof body.docs === 'string' ? JSON.parse(body.docs) : (body.docs ?? []);
  } catch (e) {
    docs = [];
  }
  if (!Array.isArray(docs)) docs = [];

  const porNombre = new Map();
  for (const d of docs) {
    if (d && d.nombre_archivo) porNombre.set(String(d.nombre_archivo), d);
  }

  const binarios = item.binary ?? {};
  // data0, data1, data10... ordenados numéricamente, no alfabéticamente
  const keys = Object.keys(binarios).sort((a, b) => {
    const na = parseInt(String(a).replace(/\D/g, ''), 10) || 0;
    const nb = parseInt(String(b).replace(/\D/g, ''), 10) || 0;
    return na - nb;
  });

  for (let i = 0; i < keys.length; i++) {
    const bin = binarios[keys[i]];
    const rawName = (bin.fileName ?? '').toString();

    let filename = rawName;
    let tipoPortal = '';
    let rama = 'desconocido';
    let documentoId = null;
    let grupoId = null;

    const meta = porNombre.get(rawName) ?? docs[i] ?? null;

    if (meta) {
      tipoPortal = (meta.tipo_doc ?? '').toString().toLowerCase();
      rama = RAMA_POR_TIPO[tipoPortal] ?? 'desconocido';
      documentoId = meta.documento_id ?? null;
      grupoId = meta.grupo_id ?? null;
    } else {
      // --- compatibilidad con el formato viejo: prefijo en el nombre ---
      const m = rawName.match(/^([a-zA-Z_]+)__([\s\S]*)$/);
      if (m && RAMAS.includes(m[1].toLowerCase())) {
        rama = m[1].toLowerCase();
        tipoPortal = rama;
        filename = m[2];
      }
      // --- fin bloque de compatibilidad ---
    }

    out.push({
      json: {
        messageId: groupId,
        threadId: groupId,
        operacion_id: operacionId || null,
        numero_operacion: numeroOp || null,
        documento_id: documentoId,
        grupo_id: grupoId,
        filename: filename || null,
        mimeType: bin.mimeType ?? null,
        tipo_portal: tipoPortal || 'otro',   // el tipo real, con sus 14 valores
        tipo_doc: RAMAS.includes(rama) ? rama : 'desconocido',  // la rama del switch
      },
      binary: { attachment_0: bin },
      pairedItem: { item: idx },
    });
  }
}

return out;

// Los documentos vienen etiquetados desde el portal (tipo_doc en Split Adjuntos).
// Ya no se clasifica por palabras clave: solo se traslada el texto extraido y la etiqueta.
const LIMITE = 30000;
const origen = $('Split Adjuntos').item.json;
const textoCompleto = ($json.text ?? JSON.stringify($json)).toString();
const texto = textoCompleto.slice(0, LIMITE);

return {
  json: {
    texto,
    tipo_doc: origen.tipo_doc ?? 'desconocido',
    messageId: origen.messageId,
    filename: origen.filename,
  },
};

