={{ (() => {
  const o = $json.output || {};

  // El modelo devuelve cantidad_comercial y cantidad_foc por separado.
  // La suma se hace aca, no en el modelo. Regla clave: si NINGUNA de las dos
  // vino, cantidad queda null. Nunca 0 - un cero silencioso en una declaracion
  // aduanera es peor que un dato faltante.
  const items = (o.items || []).map((it) => {
    const c = it.cantidad_comercial;
    const f = it.cantidad_foc;
    const hayC = c !== null && c !== undefined && c !== '';
    const hayF = f !== null && f !== undefined && f !== '';

    let cantidad;
    if (hayC || hayF) {
      cantidad = (hayC ? Number(c) || 0 : 0) + (hayF ? Number(f) || 0 : 0);
    } else {
      // Respaldo por si el schema viejo todavia devuelve 'cantidad'.
      cantidad = it.cantidad ?? null;
    }

    return { ...it, cantidad };
  });

  return { ...o, items };
})() }}

={{ (() => {
  const o = $json.output || {};
  const t = o.tabla || {};
  const texto = String($('Clasificar Documento').item.json.texto || '');

  const num = (v) => {
    if (v === null || v === undefined || v === '') return null;
    if (typeof v === 'number') return v;
    let s = String(v).trim().replace(/[^\d.,-]/g, '');
    if (s === '') return null;
    const iC = s.lastIndexOf(','), iP = s.lastIndexOf('.');
    if (iC !== -1 && iP !== -1) { if (iC > iP) s = s.replace(/\./g, '').replace(',', '.'); else s = s.replace(/,/g, ''); }
    else if (iC !== -1) { s = s.replace(',', '.'); }
    const f = parseFloat(s);
    return isNaN(f) ? null : f;
  };

  // Parser de linea CSV que respeta comillas: "169,50 " es UNA celda.
  const parseCSV = (linea) => {
    const out = []; let cur = ''; let dentro = false;
    for (let i = 0; i < linea.length; i++) {
      const ch = linea[i];
      if (ch === '"') {
        if (dentro && linea[i + 1] === '"') { cur += '"'; i++; }
        else dentro = !dentro;
      } else if (ch === ',' && !dentro) { out.push(cur); cur = ''; }
      else cur += ch;
    }
    out.push(cur);
    return out.map((c) => c.trim());
  };

  const lineas = texto.split(/\r?\n/);
  const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim();

  // Ubicar donde arrancan los datos. Primero por la fila que indico el modelo;
  // si no aparece textual, por la linea siguiente al encabezado.
  let inicio = -1;
  const objetivo = norm(t.primera_fila_datos_texto);
  if (objetivo) {
    inicio = lineas.findIndex((l) => norm(l) === objetivo);
    if (inicio === -1) {
      const prefijo = objetivo.slice(0, 40);
      inicio = lineas.findIndex((l) => norm(l).startsWith(prefijo));
    }
  }
  if (inicio === -1 && norm(t.encabezado_texto)) {
    const h = lineas.findIndex((l) => norm(l) === norm(t.encabezado_texto));
    if (h !== -1) inicio = h + 1;
  }

  const col = (fila, n) => (n && n >= 1 && n <= fila.length) ? fila[n - 1] : '';

  const detalle_lineas = [];
  let leidas = 0;
  if (inicio !== -1 && t.col_numero_parte) {
    for (let i = inicio; i < lineas.length; i++) {
      const bruta = lineas[i];
      if (!bruta || !bruta.trim()) continue;
      const fila = parseCSV(bruta);
      leidas++;
      const parte = col(fila, t.col_numero_parte);
      if (!parte) continue; // encabezados, totales y pies quedan afuera
      const c = num(col(fila, t.col_cantidad_comercial));
      const f = num(col(fila, t.col_cantidad_foc));
      if (c === null && f === null) continue;
      detalle_lineas.push({
        numero_parte: parte,
        cantidad_comercial: c,
        cantidad_foc: f,
        cantidad: (c || 0) + (f || 0),
        contenedor: col(fila, t.col_contenedor) || null,
        peso_bruto: num(col(fila, t.col_peso_bruto)),
        cantidad_bultos: num(col(fila, t.col_bultos)),
      });
    }
  }

  // Contenedores: identidad del modelo, numeros sumados de los renglones.
  const agr = {};
  for (const l of detalle_lineas) {
    const k = String(l.contenedor || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    if (!k) continue;
    if (!agr[k]) agr[k] = { peso: 0, bultos: 0, hayPeso: false, hayBultos: false };
    if (l.peso_bruto !== null) { agr[k].peso += l.peso_bruto; agr[k].hayPeso = true; }
    if (l.cantidad_bultos !== null) { agr[k].bultos += l.cantidad_bultos; agr[k].hayBultos = true; }
  }

  const contenedores_detalle = (o.contenedores_detalle || []).map((cc) => {
    const k = String(cc.contenedor || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
    const a = agr[k];
    return {
      ...cc,
      peso_bruto: a && a.hayPeso ? a.peso.toFixed(2) : null,
      cantidad_bultos: a && a.hayBultos ? a.bultos : null,
    };
  });

  const declarados = num(o.cantidad_contenedores);
  const cantidad_contenedores = declarados !== null ? declarados : (contenedores_detalle.length || null);

  const totC = num(o.cantidad_total_comercial), totF = num(o.cantidad_total_foc);
  const cantidad_total = (totC === null && totF === null) ? null : (totC || 0) + (totF || 0);

  return {
    ...o,
    detalle_lineas,
    contenedores_detalle,
    cantidad_total_comercial: totC,
    cantidad_total_foc: totF,
    cantidad_total,
    cantidad_contenedores,
    // Para auditar la extraccion desde el cuadro comparativo.
    extraccion: {
      lineas_leidas: leidas,
      renglones_extraidos: detalle_lineas.length,
      inicio_encontrado: inicio !== -1,
      texto_truncado: texto.length >= 30000,
    },
  };
})() }}

