const b = $json.body ?? {};
const padreId = 'YOUR_DRIVE_ROOT_FOLDER_ID';
const clean = (s) => (s ?? '').toString().trim().replace(/[\\/'"\n\r]/g, '').replace(/\s+/g, ' ');
const cliente = clean(b.cliente) || 'Sin cliente';
const operacion = clean(b.numero_operacion) || ('op_' + Date.now());
const modo = clean(b.modo_transporte) || 'sin especificar';
const now = new Date();
const anio = String(now.getFullYear());
const mes = String(now.getMonth() + 1).padStart(2, '0');
return [{ json: { padreId, cliente, anio, mes, operacion, modo } }];

const folderId = $('ID Operación').item.json.parentId;
