// Cuadro comparativo de la operacion: una fila por concepto, una columna por
// documento. Muestra los cuatro valores lado a lado en vez de solo las
// diferencias, para poder auditar la operacion completa de un vistazo.
//
// Convenciones de celda:
//   valor           el documento declara el dato
//   null            el documento deberia traerlo y no vino
//   —               el concepto no aplica a ese documento
//   sin documento   ese documento no llego en este legajo
//
// Estados de la fila:
//   SI   los documentos que declaran el dato coinciden
//   NO   no coinciden
//   NA   NO VERIFICABLE: dos o mas documentos presentes deberian traer el dato
//        y al menos uno no lo trajo. NO es lo mismo que "coincide": es que no
//        se pudo comparar. Antes esto salia como '-' y se veia igual que un OK.
//   -    no hay cruce posible por diseño (un solo documento declara el dato)
const grab = (n) => { try { const a = $(n).all(); return a.length ? a[0].json : null; } catch (e) { return null; } };
const jFac = grab('Doc Factura'), jAnx = grab('Doc Anexo'), jPl = grab('Doc PL'), jBl = grab('Doc Transporte');
const fac = jFac?.doc ?? null, anx = jAnx?.doc ?? null, pl = jPl?.doc ?? null, bl = jBl?.doc ?? null;
// El numero de operacion sale del webhook, que es donde lo tipeo el analista.
// Los documentos son el respaldo por si el body no lo trajera.
const bodyWebhook = (() => { try { return $('Portal Documentos').first().json.body ?? {}; } catch (e) { return {}; } })();
const operacion = String(bodyWebhook.numero_operacion ?? '').trim()
  || jFac?.messageId || jAnx?.messageId || jPl?.messageId || jBl?.messageId
  || 'Sin operacion';
const COLS = [
  { k: 'fac', titulo: 'Factura', doc: fac },
  { k: 'anx', titulo: 'Anexo', doc: anx },
  { k: 'pl', titulo: 'Packing List', doc: pl },
  { k: 'bl', titulo: 'Certificado', doc: bl },
];
const S = (v) => (v === undefined || v === null) ? '' : v.toString().trim();
const K = (v) => S(v).toUpperCase().replace(/[^A-Z0-9]/g, '');
const N = (v) => { if (v === undefined || v === null) return null; let s = v.toString().trim().replace(/[^\d.,-]/g, ''); if (s === '') return null; if (s.includes('.') && s.includes(',')) s = s.replace(/\./g, '').replace(',', '.'); else if (s.includes(',')) s = s.replace(',', '.'); const f = parseFloat(s); return isNaN(f) ? null : f; };
// Pesos: conviven formato US (22,723.60) y europeo (22.723,60). El ultimo separador manda.
const P = (v) => { if (v === undefined || v === null) return null; let s = v.toString().trim().replace(/[^\d.,-]/g, ''); if (s === '') return null; const iC = s.lastIndexOf(','), iP = s.lastIndexOf('.'); if (iC !== -1 && iP !== -1) { if (iC > iP) s = s.replace(/\./g, '').replace(',', '.'); else s = s.replace(/,/g, ''); } else if (iC !== -1) { s = s.replace(',', '.'); } const f = parseFloat(s); return isNaN(f) ? null : f; };
const filas = [];
// Si una clave NO esta en vals, el concepto no aplica a ese documento.
const fila = (grupo, concepto, vals, modo) => filas.push({ grupo, concepto, vals, modo: modo || 'texto' });
// ---------- CABECERA ----------
fila('Cabecera', 'N° invoice', { fac: fac?.numero_invoice ?? null, anx: anx?.numero_invoice ?? null });
fila('Cabecera', 'Cliente / Importador', { fac: fac?.cliente_importador ?? null, anx: anx?.cliente_importador ?? null });
fila('Cabecera', 'Proveedor', { fac: fac?.proveedor ?? null, anx: anx?.proveedor ?? null });
fila('Cabecera', 'PO N°', { fac: fac?.po_numero ?? null, anx: anx?.po_numero ?? null, pl: pl?.po_numero ?? null, bl: bl?.po_numero ?? null });
fila('Cabecera', 'NCM', { pl: pl?.ncm ?? null, bl: bl?.ncm ?? null });
const paisesAnexo = [...new Set((anx?.items || []).map((i) => S(i.pais_origen).toUpperCase()).filter(Boolean))];
fila('Cabecera', 'País de origen', { fac: fac?.pais_origen ?? null, anx: paisesAnexo.length ? paisesAnexo.join(' / ') : null, bl: bl?.pais_origen ?? null });
fila('Cabecera', 'Moneda', { fac: fac?.moneda ?? null });
fila('Cabecera', 'Incoterm', { fac: fac?.incoterm ?? null });
fila('Cabecera', 'N° de conocimiento', { bl: bl?.numero_conocimiento ?? null });
fila('Cabecera', 'Transporte', { bl: bl?.transporte ?? null });
fila('Cabecera', 'Flete Collect / Prepaid', { bl: bl?.flete_condicion ?? null });
// ---------- IMPORTES ----------
fila('Importes', 'Valor FOB total', { fac: fac?.valor_fob_total ?? null }, 'numero');
fila('Importes', 'Flete', { fac: fac?.flete ?? null, bl: bl?.flete ?? null }, 'numero');
fila('Importes', 'Seguro', { fac: fac?.seguro ?? null, bl: bl?.seguro ?? null }, 'numero');
// ---------- CANTIDADES ----------
const sumaCampo = (arr, campo) => { if (!Array.isArray(arr) || !arr.length) return null; let t = 0, hubo = false; for (const x of arr) { const n = N(x[campo]); if (n !== null) { t += n; hubo = true; } } return hubo ? t : null; };
fila('Cantidades', 'Cantidad total declarada', { fac: fac?.cantidad_total ?? null, anx: anx?.cantidad_total ?? null, pl: pl?.cantidad_total ?? null }, 'numero');
fila('Cantidades', 'Suma de los renglones', {
  fac: fac ? sumaCampo(fac.items, 'cantidad') : null,
  anx: anx ? sumaCampo(anx.items, 'cantidad') : null,
  pl: pl ? sumaCampo(pl.detalle_lineas, 'cantidad') : null,
}, 'numero');
fila('Cantidades', 'Renglones extraídos (informativo)', {
  fac: fac ? (fac.items || []).length : null,
  anx: anx ? (anx.items || []).length : null,
  pl: pl ? (pl.detalle_lineas || []).length : null,
}, 'ninguno');
// Una fila por numero de parte. El packing list repite la parte por contenedor,
// asi que se agrupa y se suma aca, en codigo.
const nombre = {};
const acumular = (arr) => { const out = {}; for (const x of (arr || [])) { const k = K(x.numero_parte); if (!k) continue; if (!nombre[k]) nombre[k] = S(x.numero_parte); const n = N(x.cantidad); out[k] = (out[k] ?? 0) + (n ?? 0); } return out; };
const qFac = acumular(fac?.items), qAnx = acumular(anx?.items), qPl = acumular(pl?.detalle_lineas);
const partes = [...new Set([...Object.keys(qFac), ...Object.keys(qAnx), ...Object.keys(qPl)])].sort();
const filasParte = [];
for (const k of partes) {
  filasParte.push({
    grupo: 'Cantidad por número de parte',
    concepto: nombre[k] || k,
    vals: { fac: fac ? (qFac[k] ?? null) : null, anx: anx ? (qAnx[k] ?? null) : null, pl: pl ? (qPl[k] ?? null) : null },
    modo: 'numero',
  });
}
// ---------- PESOS Y TOTALES ----------
fila('Pesos y contenedores', 'Peso neto total', { pl: pl?.peso_neto ?? null }, 'peso');
fila('Pesos y contenedores', 'Peso bruto total', { pl: pl?.peso_bruto ?? null, bl: bl?.peso_bruto_total ?? null }, 'peso');
fila('Pesos y contenedores', 'Cantidad de contenedores', { pl: pl?.cantidad_contenedores ?? null, bl: bl?.cantidad_contenedores ?? null }, 'numero');
// ---------- POR CONTENEDOR ----------
// Los pesos y bultos del lado PL los calcula Doc PL sumando los renglones de
// cada contenedor. Los del BL: peso de contenedores_detalle, bultos de
// mercaderia_detalle agrupado por contenedor.
const mapC = (arr) => { const m = {}; for (const c of (arr || [])) { const k = K(c.contenedor); if (k) m[k] = c; } return m; };
const cPl = mapC(pl?.contenedores_detalle), cBl = mapC(bl?.contenedores_detalle);
const bultosBl = {};
for (const m of (bl?.mercaderia_detalle || [])) {
  const k = K(m.contenedor);
  if (!k) continue;
  const n = N(m.cantidad_bultos);
  if (n !== null) bultosBl[k] = (bultosBl[k] ?? 0) + n;
}
for (const k of [...new Set([...Object.keys(cPl), ...Object.keys(cBl)])].sort()) {
  const et = S(cPl[k]?.contenedor || cBl[k]?.contenedor) || k;
  fila('Contenedores', et + ' · Precinto', { pl: cPl[k]?.precinto ?? null, bl: cBl[k]?.precinto ?? null });
  fila('Contenedores', et + ' · Peso bruto', { pl: cPl[k]?.peso_bruto ?? null, bl: cBl[k]?.peso_bruto ?? null }, 'peso');
  fila('Contenedores', et + ' · Bultos', { pl: cPl[k]?.cantidad_bultos ?? null, bl: bultosBl[k] ?? null }, 'numero');
}
// ---------- EVALUACION ----------
// La distincion que importa:
//   "esperados" = documentos que SI llegaron y que por diseño declaran este dato.
//   Si esperados < 2 no hay cruce posible: '-' (no es una falla).
//   Si esperados >= 2 pero alguno no trajo el valor: 'NA' (no verificable).
//   Antes los dos casos daban '-' y una fila sin comparar se veia igual que un OK.
const evaluar = (f) => {
  if (f.modo === 'ninguno') return '-';
  const claves = Object.keys(f.vals);
  const tiene = (k) => { const v = f.vals[k]; return v !== null && v !== undefined && v !== ''; };
  const esperados = claves.filter((k) => COLS.find((c) => c.k === k)?.doc);
  const presentes = esperados.filter(tiene);
  if (esperados.length < 2) return '-';
  // Nadie lo declaro: no hay nada que comparar y ya se ve como null en la tabla.
  // Marcarlo NA floodearia todos los campos opcionales (flete y seguro en FOB, por ejemplo).
  if (presentes.length === 0) return '-';
  // Alguno si y alguno no: ESTE es el caso peligroso, el que antes se veia como un OK.
  if (presentes.length < esperados.length) return 'NA';
  const conv = f.modo === 'peso' ? P : (f.modo === 'numero' ? N : K);
  const tol = f.modo === 'peso' ? 0.5 : (f.modo === 'numero' ? 0.01 : 0);
  const base = conv(f.vals[presentes[0]]);
  for (const k of presentes.slice(1)) {
    const otro = conv(f.vals[k]);
    if (base === null || otro === null) return 'NA';
    if (f.modo === 'texto') { if (base !== otro) return 'NO'; }
    else if (Math.abs(base - otro) > tol) return 'NO';
  }
  return 'SI';
};
const todas = [...filas.filter((f) => f.grupo !== 'Contenedores'), ...filasParte, ...filas.filter((f) => f.grupo === 'Contenedores')];
for (const f of todas) f.estado = evaluar(f);
const conflictos = todas.filter((f) => f.estado === 'NO').length;
const noVerificables = todas.filter((f) => f.estado === 'NA').length;
// Si hay muchisimas partes, mostrar solo las que tienen conflicto o no se pudieron verificar.
const MAX_PARTES = 40;
let recorte = null;
let visibles = todas;
if (filasParte.length > MAX_PARTES) {
  const ocultas = filasParte.filter((f) => f.estado === 'SI' || f.estado === '-').length;
  visibles = todas.filter((f) => f.grupo !== 'Cantidad por número de parte' || f.estado === 'NO' || f.estado === 'NA');
  recorte = filasParte.length + ' números de parte en total. Se listan solo los ' + (filasParte.length - ocultas) + ' con diferencia o sin verificar; ' + ocultas + ' coinciden y se omitieron.';
}
// ---------- HTML ----------
const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const fecha = new Date().toLocaleString('es-AR', { timeZone: 'America/Argentina/Buenos_Aires' });
const TH = 'padding:9px 10px;text-align:left;font-size:11px;letter-spacing:.04em;text-transform:uppercase;color:#6b7280;border-bottom:1px solid #e5e7eb;font-weight:600;';
const TD = 'padding:8px 10px;font-size:13px;line-height:1.4;border-bottom:1px solid #f1f5f9;vertical-align:top;';
const celda = (f, col) => {
  if (!(col.k in f.vals)) return '<span style="color:#d1d5db;">—</span>';
  if (!col.doc) return '<span style="color:#d1d5db;font-style:italic;">sin documento</span>';
  const v = f.vals[col.k];
  if (v === null || v === undefined || v === '') return '<span style="color:#b45309;font-family:monospace;font-size:12px;">null</span>';
  return esc(v);
};
let cuerpo = '';
const grupos = [];
for (const f of visibles) { if (!grupos.length || grupos[grupos.length - 1].nombre !== f.grupo) grupos.push({ nombre: f.grupo, filas: [] }); grupos[grupos.length - 1].filas.push(f); }
for (const g of grupos) {
  cuerpo += '<div style="margin:22px 0 8px;font-size:12px;font-weight:700;color:#111827;text-transform:uppercase;letter-spacing:.05em;">' + esc(g.nombre) + '</div>';
  cuerpo += '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #e5e7eb;border-radius:6px;">';
  cuerpo += '<tr style="background:#f9fafb;"><th style="' + TH + 'width:26%;">Concepto</th>';
  for (const c of COLS) cuerpo += '<th style="' + TH + '">' + esc(c.titulo) + '</th>';
  cuerpo += '</tr>';
  for (const f of g.filas) {
    const malo = f.estado === 'NO';
    const dudoso = f.estado === 'NA';
    const bg = malo ? 'background:#fef2f2;' : (dudoso ? 'background:#fffbeb;' : '');
    const marca = malo
      ? '<span style="color:#b91c1c;font-weight:700;margin-right:6px;">≠</span>'
      : (dudoso ? '<span style="color:#b45309;font-weight:700;margin-right:6px;" title="No verificable">?</span>' : '');
    cuerpo += '<tr style="' + bg + '">';
    cuerpo += '<td style="' + TD + 'font-weight:600;color:#111827;">' + marca + esc(f.concepto) + '</td>';
    for (const c of COLS) cuerpo += '<td style="' + TD + 'color:#111827;">' + celda(f, c) + '</td>';
    cuerpo += '</tr>';
  }
  cuerpo += '</table>';
  if (g.nombre === 'Cantidad por número de parte' && recorte) {
    cuerpo += '<div style="margin-top:6px;font-size:11px;color:#6b7280;">' + esc(recorte) + '</div>';
  }
}
const faltantes = COLS.filter((c) => !c.doc).map((c) => c.titulo);
const aviso = faltantes.length
  ? '<div style="background:#fffbeb;border:1px solid #fde68a;border-radius:6px;padding:10px 14px;margin:0 0 4px;color:#92400e;font-size:12px;">No llegó: ' + esc(faltantes.join(', ')) + '</div>'
  : '';
// El chip de arriba: rojo si hay diferencias, ambar si no hay diferencias pero
// quedaron conceptos sin poder verificar, verde solo si esta todo cruzado.
const chipBg = conflictos ? '#fee2e2' : (noVerificables ? '#fef3c7' : '#d1fae5');
const chipColor = conflictos ? '#b91c1c' : (noVerificables ? '#92400e' : '#047857');
const titulo = conflictos
  ? conflictos + ' concepto' + (conflictos === 1 ? '' : 's') + ' con diferencia'
  : (noVerificables ? 'Sin diferencias, pero ' + noVerificables + ' sin verificar' : 'Todos los conceptos coinciden');
const subChip = (conflictos && noVerificables)
  ? '<span style="display:inline-block;background:#fef3c7;color:#92400e;border-radius:12px;padding:3px 12px;font-size:12px;font-weight:600;margin-left:6px;">' + noVerificables + ' sin verificar</span>'
  : '';
const html =
  '<div style="font-family:-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Helvetica,Arial,sans-serif;max-width:900px;margin:0 auto;padding:24px;color:#111827;">' +
  '<div style="border-bottom:2px solid #111827;padding-bottom:14px;margin-bottom:16px;">' +
  '<div style="font-size:11px;letter-spacing:.08em;text-transform:uppercase;color:#6b7280;margin-bottom:6px;">Cuadro comparativo de la operación</div>' +
  '<div style="font-size:20px;font-weight:700;">' + esc(operacion) + '</div>' +
  '<div style="margin-top:10px;">' +
  '<span style="display:inline-block;background:' + chipBg + ';color:' + chipColor + ';border-radius:12px;padding:3px 12px;font-size:12px;font-weight:600;">' + titulo + '</span>' +
  subChip +
  '<span style="color:#6b7280;font-size:12px;margin-left:10px;">' + todas.length + ' conceptos &middot; ' + fecha + '</span>' +
  '</div></div>' +
  aviso +
  cuerpo +
  '<div style="margin-top:20px;padding-top:14px;border-top:1px solid #e5e7eb;color:#9ca3af;font-size:11px;line-height:1.6;">' +
  '<strong style="color:#6b7280;">Cómo leer:</strong> ' +
  '<span style="color:#b91c1c;font-weight:700;">≠</span> los documentos que declaran el dato no coinciden &middot; ' +
  '<span style="color:#b45309;font-weight:700;">?</span> no verificable: dos documentos deberían traer el dato y uno no lo trajo &middot; ' +
  '<span style="color:#b45309;font-family:monospace;">null</span> el documento debería traerlo y no vino &middot; ' +
  '<span style="color:#d1d5db;">—</span> el concepto no aplica a ese documento' +
  '</div></div>';
const partesAsunto = [];
if (conflictos) partesAsunto.push(conflictos + ' diferencia' + (conflictos === 1 ? '' : 's'));
if (noVerificables) partesAsunto.push(noVerificables + ' sin verificar');
const asunto = partesAsunto.length
  ? '[Cruces] ' + partesAsunto.join(' y ') + ' - ' + operacion
  : '[Cruces] Sin diferencias - ' + operacion;
return [{ json: { asunto, html, operacion, filas: todas, total_conceptos: todas.length, total_diferencias: conflictos, total_no_verificables: noVerificables, documentos_faltantes: faltantes } }];

