  // Pais de origen: la factura primero, el BL como respaldo.
  // 'origen' del BL es el puerto (ej. 'SHEKOU PT, CHINA'); el campo bueno es pais_origen.
  const paisFactura = $('Doc Factura').isExecuted ? ($('Doc Factura').first().json.doc?.pais_origen ?? null) : null;
  const paisTransporte = $('Doc Transporte').isExecuted ? ($('Doc Transporte').first().json.doc?.pais_origen ?? null) : null;
  const paisCabecera = paisFactura ?? paisTransporte ?? null;
  const paisFuente = paisFactura ? 'factura' : (paisTransporte ? 'transporte' : 'sin dato');

  // El anexo manda. La factura solo entra si no hubo anexo.
  const fuente = anexo.length ? 'anexo' : 'factura';
  const base = anexo.length ? anexo : factura;

  // Indice de la factura por numero de parte, para completar huecos del anexo.
  const idxFactura = {};
  for (const f of factura) {
    const k = norm(f.numero_parte);
    if (k) idxFactura[k] = f;
  }

  return base.map((r) => {
    const k = norm(r.numero_parte);
    const enFactura = k ? idxFactura[k] : null;
    return {
      numero_parte: r.numero_parte ?? null,
      descripcion: r.descripcion ?? null,
      cantidad: r.cantidad ?? null,
      precio_unitario: r.precio_unitario ?? enFactura?.precio_unitario ?? null,
      unidad: r.unidad_medida ?? enFactura?.unidad_medida ?? null,
      // Si algun dia el item trae su propio pais, ese gana sobre el de cabecera.
      pais: r.pais_origen ?? enFactura?.pais_origen ?? paisCabecera,
      pais_fuente: r.pais_origen || enFactura?.pais_origen ? 'item' : paisFuente,
      fuente: fuente,
    };
  });
})() }}

