// Arma una fila por archivo subido, lista para insertar en la tabla `documentos`,
// más los datos de la carpeta de Drive para actualizar la operación.
const body = $('Portal Documentos').first().json.body ?? {};
const operacionId = String(body.operacion_id ?? '').trim();
const carpetaId = $('ID Operación').first().json.parentId;

// Tipos declarados por el operador en el portal
let docs = [];
try {
  docs = typeof body.docs === 'string' ? JSON.parse(body.docs) : (body.docs ?? []);
} catch (e) { docs = []; }
if (!Array.isArray(docs)) docs = [];

const porNombre = new Map();
for (const d of docs) if (d && d.nombre_archivo) porNombre.set(String(d.nombre_archivo), d);

// Lo que extrajo cada agente de IA, indexado por nombre de archivo
const extraccion = {};
for (const nodo of ['Doc Factura', 'Doc Anexo', 'Doc PL', 'Doc Transporte']) {
  try {
    for (const it of $(nodo).all()) {
      const f = it.json?.filename;
      if (f) extraccion[f] = it.json?.doc ?? null;
    }
  } catch (e) { /* ese documento no llegó en este legajo */ }
}

const subidos = $input.all();               // salida de "Ubicar en carpeta"
const meta = $('Archivos a subir').all();   // nombre y tipo con los que se subió

const filas = subidos.map((it, i) => {
  const driveId = it.json?.id ?? null;
  const nombre = it.json?.name ?? meta[i]?.json?.filename ?? null;
  const d = porNombre.get(nombre) ?? {};

  const fila = {
    operacion_id: operacionId,
    tipo: d.tipo_doc || 'otro',
    nombre_archivo: nombre,
    drive_file_id: driveId,
    drive_url: driveId ? 'https://drive.google.com/file/d/' + driveId + '/view' : null,
    origen: 'n8n',
  };
  // grupo_id solo si es un reemplazo: si va null, el insert falla (la columna es NOT NULL
  // con default). Omitirlo deja que Postgres genere uno nuevo.
  if (d.grupo_id) fila.grupo_id = d.grupo_id;
  if (extraccion[nombre]) fila.extraccion = extraccion[nombre];
  return fila;
});

return [{
  json: {
    operacion_id: operacionId,
    drive_folder_id: carpetaId,
    drive_folder_url: 'https://drive.google.com/drive/folders/' + carpetaId,
    filas,
  },
}];

